from register.models import *
from transaction.models import *
from datetime import date, datetime


class Att:
	def QLvl(u):
		j=[]
		for i in Transaction.objects.filter(tdate__date=datetime.now().date(), level=u.level, service=u.service).distinct("register_id"):
			j.append(i.register.k_id)
		return j
	def atcheck(u):
		if Transaction.objects.filter(tdate__date=datetime.now().date(), register_id=Register.objects.get(k_id=u.k_id).id, service=u.service).latest("id").status == "1":
			return u.k_id
	def stat_io(u):
		if len(Transaction.objects.filter(tdate__date=datetime.now().date(), register_id=Register.objects.get(k_id=u.k_id).id, service=u.service, status=1))%2 == len(Transaction.objects.filter(tdate__date=datetime.now().date(), register_id=Register.objects.get(k_id=u.k_id).id, service=u.service, status=0))%2:
			return u.k_id

class Total:
	def CService(u):
		j={}
		for i in Transaction.objects.filter(tdate__date=date.fromisoformat(u.date), service=u.service).distinct('register_id'):
			if i.service in j:
				j[i.service].append([", ".join([i.register.lastname, i.register.firstname]), i.level])			
			else:
				j[i.service]=[", ".join([i.register.lastname, i.register.firstname]), i.level]
		return j
	def CSTotal(u):
		j={}
		for i in Transaction.objects.filter(tdate__date=date.fromisoformat(u.date)).distinct('register_id'):
			if i.service in j:
				j[i.service].append([i.register.k_id])			
			else:
				j[i.service]=[i.register.k_id]
		totalservice={}
		for i in j:
			totalservice[i]=len(j[i])
		return totalservice
